            function loadData(content, filter) {
                var prom = content.call("LoadData", { inputDto: filter })
                    .done((ret) => {
                    if (content.grid.hasClass("ggrid")) {
                        content.dataView.updateData(ret);
                        content.grid.ggrid("setData", content.dataView);
                    }
                });
                return prom;
            }
            WebControls.loadData = loadData;
